// Arrow key nudging: Move selected element by 1px (10px with Shift)
if (e.key === 'ArrowUp' || e.key === 'ArrowDown' || e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
  if (selectedElementIds.length > 0 && selectedSceneId) {
    e.preventDefault();
    const nudge = e.shiftKey ? 10 : 1;
    const currentScene = selectCurrentScene(project, selectedSceneId);
    for (const elId of selectedElementIds) {
      const el = currentScene?.elements.find((candidate) => candidate.id === elId);
      if (el?.locked) continue;
      const dx = e.key === 'ArrowLeft' ? -nudge : e.key === 'ArrowRight' ? nudge : 0;
      const dy = e.key === 'ArrowUp' ? -nudge : e.key === 'ArrowDown' ? nudge : 0;
      dispatch({
        type: 'element/move',
        payload: {
          sceneId: selectedSceneId,
          elementId: elId,
          transform: {
            x: el!.transform.x + dx,
            y: el!.transform.y + dy,
          },
        },
      });
    }
    return;
  }
}

